WITH latest AS (
  SELECT max(snapshot_date) AS d FROM daily_site_metrics
),
hist AS (
  SELECT max(snapshot_date) AS d FROM daily_site_metrics, latest
  WHERE snapshot_date::date <= latest.d::date - 7
),
now_v AS (
  SELECT coalesce(sum(total),0) AS v FROM daily_site_metrics, latest
  WHERE site_label IN ($site) AND snapshot_date = latest.d
),
then_v AS (
  SELECT coalesce(sum(total),0) AS v FROM daily_site_metrics, hist
  WHERE site_label IN ($site) AND snapshot_date = hist.d
)
SELECT (now_v.v - then_v.v) AS delta FROM now_v, then_v;

